import os
from azure.ai.formrecognizer import DocumentAnalysisClient
from azure.core.credentials import AzureKeyCredential

def extract_invoice_fields(payload, config=None):
    config = config or {}
    endpoint = config.get("endpoint") or os.environ["AZURE_FORM_RECOGNIZER_ENDPOINT"]
    api_key = config.get("api_key") or os.environ["AZURE_FORM_RECOGNIZER_KEY"]
    client = DocumentAnalysisClient(endpoint=endpoint, credential=AzureKeyCredential(api_key))
    poller = client.begin_analyze_document("prebuilt-invoice", document=payload)
    invoice = poller.result().documents[0] if poller.result().documents else None

    def _field_value(field):
        if not field:
            return None
        if getattr(field, "value", None) is not None:
            return field.value
        return field.content

    result = {
        "vendor": None,
        "date": None,
        "total": None,
        "line_items": [],
    }

    if invoice:
        fields = invoice.fields or {}
        result["vendor"] = _field_value(fields.get("VendorName"))
        result["date"] = _field_value(fields.get("InvoiceDate"))
        result["total"] = _field_value(fields.get("InvoiceTotal"))

        items = fields.get("Items")
        if items and getattr(items, "value", None):
            for item in items.value:
                item_fields = getattr(item, "value", {}) or {}
                result["line_items"].append({
                    "description": _field_value(item_fields.get("Description")),
                    "quantity": _field_value(item_fields.get("Quantity")),
                    "unit_price": _field_value(item_fields.get("UnitPrice")),
                    "amount": _field_value(item_fields.get("Amount")),
                })
    return result
